export const videoViewTitle='Giving a twist ending to a story';
export function videoViewHTML({mode='normal'}={}){
  return `<!doctype html><html><body><style>
  body{font:15px Arial}.video-box,.question-video-player{position:relative;width:640px;height:400px;margin:20px}video{width:640px;height:360px;background:#234}.vjs-control-bar{position:absolute;bottom:0;height:44px;width:640px;background:#345}.vjs-progress-holder,.ant-slider{position:absolute;top:0;width:640px;height:8px;background:#bbb}.vjs-slider-handle,.ant-slider-handle{position:absolute;top:-1px;left:0;width:10px;height:10px;background:#08e;transform:translateX(-50%)}.vjs-play-control,.iconbtn{position:absolute;left:10px;top:12px;width:50px;height:25px}
  </style><header><div class="pc-break-crumb"><span class="pc-break-crumb-text">English Book</span><span class="pc-break-crumb-text">Horns of a dilemma</span><span class="pc-break-crumb-text">Analyzing writing techniques</span></div><div class="pc-header-tab-activity">${videoViewTitle}</div><div class="pc-task pc-header-task-activity">${videoViewTitle}</div></header>
  <main class="layout-container"><div class="abs-direction">Watch the video and learn about the skills of giving a twist ending to a story.</div><div class="video-box video-js"><video preload="auto" src="https://ucontent.unipus.cn/offline-recognition/video-view.webm"></video><div class="vjs-control-bar"><div class="vjs-progress-holder" role="slider" aria-label="视频进度"><div class="vjs-slider-handle"></div></div><button class="vjs-play-control" aria-label="播放">播放</button></div></div></main>
  <script>
  const video=document.querySelector('video'),button=document.querySelector('.vjs-play-control'),track=document.querySelector('.vjs-progress-holder'),thumb=document.querySelector('.vjs-slider-handle'),mode=${JSON.stringify(mode)};
  window.playClicks=0;window.dragStarts=0;window.seekRequests=[];window.nativeEnds=0;window.syntheticEnds=0;window.videoPointerTrusted=[];window.seekEvents=[];window.playerActions=[];
  if(['wrapped-player','unipus-slider','poster-overlay','autohide-controls'].includes(mode)){const box=document.querySelector('.video-box'),inner=document.createElement('div'),outer=document.createElement('div');box.classList.remove('video-js');inner.className='video-js vjs-controls-disabled';outer.className='question-video-point-read';box.replaceWith(outer);outer.append(box);video.replaceWith(inner);inner.append(video);inner.insertAdjacentHTML('beforeend','<div hidden><button class="vjs-play-control">Hidden play</button><div class="vjs-progress-holder"></div></div>');if(mode!=='wrapped-player'){box.className='question-video-player';button.className='anticon anticon-play iconbtn';track.className='ant-slider';track.removeAttribute('role');track.removeAttribute('aria-label');thumb.className='ant-slider-handle';thumb.setAttribute('role','slider');thumb.setAttribute('aria-label','视频进度');}}
  if(mode==='poster-overlay'||mode==='autohide-controls'){
    const inner=video.parentElement;inner.insertAdjacentHTML('beforeend','<div class="vjs-text-track-display" aria-hidden="true"></div><div class="vjs-poster" tabindex="-1"></div>');
    document.head.insertAdjacentHTML('beforeend','<style>.vjs-poster,.vjs-text-track-display{position:absolute;left:0;top:0;width:640px;height:360px;z-index:2;pointer-events:auto}.vjs-poster{background:#234}.vjs-control-bar{z-index:3}</style>');
    video.addEventListener('playing',()=>inner.querySelector('.vjs-poster').hidden=true);
    if(mode==='autohide-controls')document.head.insertAdjacentHTML('beforeend','<style>.question-video-player .vjs-control-bar{opacity:0;pointer-events:none}.question-video-player:hover .vjs-control-bar{opacity:1;pointer-events:auto}</style>');
  }
  video.addEventListener('ended',event=>{if(event.isTrusted)window.nativeEnds++;else window.syntheticEnds++;});
  video.addEventListener('timeupdate',()=>{thumb.style.left=(video.currentTime/(video.duration||1)*100)+'%';});
  button.onclick=()=>{window.playClicks++;window.playerActions.push({kind:video.paused?'play':'pause',time:video.currentTime});if(mode==='blocked')return;if(video.paused){video.play();if(mode==='hide-track-on-play')track.hidden=true;if(mode==='popup'&&!document.querySelector('.questionReplyBox'))document.querySelector('.video-box').insertAdjacentHTML('beforeend','<div class="questionReplyBox"><label><input type="radio" name="popup">Choose an answer</label></div>');}else video.pause();};
  let dragging=false,resume=false;
  function seek(event){if(mode==='inert')return;const box=track.getBoundingClientRect();let fraction=Math.max(0,Math.min(1,(event.clientX-box.left)/box.width));if(mode==='end-clamp')fraction=Math.round(fraction);window.seekEvents.push([event.type,event.clientX,box.left,box.width,fraction]);video.currentTime=fraction*video.duration;}
  track.addEventListener('mousedown',event=>{window.dragStarts++;window.playerActions.push({kind:'drag',paused:video.paused,time:video.currentTime});window.videoPointerTrusted.push(event.isTrusted);dragging=true;resume=!video.paused;video.pause();seek(event);});
  document.addEventListener('mousemove',event=>{if(dragging)seek(event);});document.addEventListener('mouseup',event=>{if(!dragging)return;seek(event);dragging=false;window.seekRequests.push(video.currentTime);if(resume&&mode!=='pause-after-seek')video.play();});
  </script></body></html>`;
}
